/**
 * Client for /api/retrofit, plus the offline snapshot (snapshot.json, generated by `python -m app.retrofit.export`).
 * With no backend every screen replays the snapshot, which is exactly what the backend produced for the same steps.
 */
import raw from './snapshot.json';

export type Verdict = 'pass' | 'fail' | 'na';
export const DIMS = ['rack', 'response', 'loop', 'availability', 'freshness', 'control'] as const;
export type Dim = (typeof DIMS)[number];
export interface CaseRow { id: string; name: string; description: string; kind: 'behavior' | 'regression'; regression_id: number | null; result: Record<Dim, Verdict>; notes: string[]; pass: boolean }
export interface Report {
  site: string; config: string; firmware: { device: string; config: string | null }; expectations_sha: string; mapping_sha: string;
  schema: { ok: boolean; issues: { where: string; problem: string }[] };
  cases: CaseRow[]; held_out: { id: string; name: string; pass: boolean }[]; sanity: { name: string; rejected: boolean; failed_cases: string[] }[];
  passed: number; total: number; pass: boolean;
}
export interface Flag { zone: number; subject: string; point: string; mapped_location: string; drawing_location: string; quote: string; doc: string; line_no: number; line: string; failing_cases: string[] }
export interface Decision {
  id: number; site: string; subject: string; value: string; decision: string; source_doc: string; source_quote: string; author: string; at: number;
  scope: Record<string, string | number>; equipment_version: string; depends_on: string[]; version: number; status: string; note: string;
}
export interface Change { before: string; after: string; why: string; source: string }
export interface Proposal { id: number; base: string; candidate: string; sha: string; base_sha: string; diff: string; changes: Change[]; by: string }
export interface Regression { id: number; site: string; decision_id: number | null; spec: { kind: string; summary: string; [k: string]: unknown }; origin: string; status: string }
export interface Pkg { version: number; mapping_sha: string; accepted_by: string; accepted_at: number; note?: string }
export interface Approval { id: number; site: string; kind: string; status: string; decided_by: string | null; detail: Record<string, unknown> }
export interface Firmware {
  from: string; to: string; point_changes: { point: string; register: number; change: string; before?: Record<string, string>; after?: Record<string, string> }[];
  affected_lines: string[]; flagged_decisions: number[]; affected_tests: string[]; before: Report; proposal: Proposal; after: Report; approval: Approval; accepted_package: Pkg | null;
}
export interface FieldCheck { id: string; what: string; status: 'required' | 'pass' | 'fail'; witnessed_by: string | null; at: number | null }
export interface Readiness {
  site: string; package: Pkg | null; ready: boolean; decisions_needing_revalidation: number[];
  software: { passed: number; total: number; tests: { id: string; name: string; pass: boolean }[]; note: string };
  field: { open: number; checks: FieldCheck[]; note: string }; ownership: { unresolved: string[] };
}
export interface LeakZone { zone: number; location: string; valve: string | null; source: string; status: string }
export interface Handover {
  site: string; package: Pkg; diff: string; open_issues: string[]; deploy: string[]; rollback: string[]; procedures: string[];
  equipment_map: { hall: string; cdu: string; racks: string[]; leak_zones: LeakZone[]; redundancy: Record<string, { effective: string; single_points: string[] }> | null };
  tests: { passed: number; total: number; expectations_sha: string }; readiness: Readiness;
}
export interface Minute {
  t: number; clock: string;
  cdu: { state: string | null; flow_lpm: number | null; supply_c: number | null; return_c: number | null; quality: 'good' | 'stale'; source_ts: string; received_ts: string };
  racks: Record<string, { gpu_c: number; throttle_pct: number; inlet_c: number }>;
  job: { steps_per_s: number; baseline: number; phase: string; heartbeat_ok: boolean } | null;
}
export interface Owner { team: string; role: string; recovered_at: number | null; visible?: boolean }
export interface Incident {
  opened_at: number; first_below_min?: number; title: string; wording: string; scope_racks: string[]; scope_from?: string; comparison_rack?: string;
  evidence?: { id: string; text: string; source: string; ts: string }[]; procedure?: { id: string; steps: string[] };
  lead?: { date: string; author: string; asset: string; note: string; label: string } | null;
  owners: Owner[]; closing_evidence: string; closable_at: number | null; status_at_end: string;
}
export interface MonitorRun {
  variant: string; title: string; kind: 'incident' | 'visibility' | 'none'; facility_only: boolean; note?: string;
  context: { from: string; package_version: number | null; cdu: string; racks: string[]; hall: string; limits: { min_secondary_flow_lpm: number; secondary_supply_c: [number, number] }; window_min: number };
  minutes: Minute[]; alarms: { rule: string; t: number; clock: string; owner: string; detail: string }[]; incident: Incident | null;
}
export interface Snapshot {
  original: string; drawing: string; flag: { report: Report; flags: Flag[]; by: string }; decision: Decision; proposal: Proposal;
  candidate_report: Report; regression: Regression; candidate_with_regression: Report;
  h2_original: string; h2_flag: { report: Report; flags: Flag[] }; h2_decision: Decision; h2_proposal: Proposal; h2_candidate_report: Report;
  package_v1: Pkg; readiness_v1: Readiness; firmware: Firmware; firmware_approved: { approval: Approval; package: Pkg }; readiness: Readiness;
  handover: Handover; handover_md: string; monitor: Record<string, MonitorRun>; evaluation?: Evaluation;
}
export interface EvalRow { scenario: string; arm: string; affected_racks_correct: boolean | null; missed: number; unnecessary: number; handoff_min: number | null; false_recovery: number; note: string }
export interface Evaluation {
  monitoring: { rows: EvalRow[]; arms: { id: string; label: string; run: boolean; why?: string }[]; scenarios: { id: string; label: string; truth: string }[] };
  modernization: { site: string; defects: { id: string; kind: string; where: string; found: boolean; by: string }[]; false_positives: string[]; engineer_actions: number; estimate: { manual_min: number; assisted_min: number; label: string } };
}
export interface Status { contract: { id: string; label: string }; sites: string[]; nemotron_key: boolean; installed_firmware: string; synthetic: boolean; label: string }

export const SNAP = raw as unknown as Snapshot;

async function j<T>(path: string, body?: unknown): Promise<T> {
  const r = await fetch(`/api/retrofit${path}`, body === undefined ? undefined : {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  });
  if (!r.ok) {
    let msg = `${r.status}`;
    try { msg = (await r.json()).detail ?? msg; } catch { /* not JSON */ }
    throw new Error(msg);
  }
  const type = r.headers.get('content-type') ?? '';
  return (type.includes('json') ? r.json() : r.text()) as Promise<T>;
}

export const rf = {
  status: () => j<Status>('/status'),
  reset: (actor: string) => j<{ status: string }>('/reset', { actor }),
  test: (site: string, config: string, firmware?: string) => j<Report>(`/sites/${site}/test`, { config, firmware }),
  flag: (site: string) => j<{ report: Report; flags: Flag[]; by: string }>(`/sites/${site}/flag`, {}),
  decide: (site: string, zone: number, author: string) => j<Decision>(`/sites/${site}/decisions`, { zone, author, decision: 'confirmed' }),
  propose: (site: string, base = 'original') => j<Proposal>(`/sites/${site}/propose`, { base }),
  saveRegression: (site: string, decision_id: number, actor: string) => j<Regression>(`/sites/${site}/regressions`, { decision_id, actor }),
  approveRegression: (id: number, actor: string) => j<Regression>(`/regressions/${id}/approve`, { actor }),
  accept: (site: string, by: string) => j<Pkg>(`/sites/${site}/accept`, { by }),
  firmware: (site: string, firmware: string) => j<Firmware>(`/sites/${site}/firmware`, { firmware }),
  approve: (site: string, id: number, by: string) => j<{ approval: Approval; package: Pkg }>(`/sites/${site}/approvals/${id}`, { status: 'approved', by }),
  readiness: (site: string) => j<Readiness>(`/sites/${site}/readiness`),
  witness: (site: string, check_id: string, witnessed_by: string, note: string) => j<FieldCheck>(`/sites/${site}/field-results`, { check_id, result: 'pass', witnessed_by, note }),
  handover: (site: string) => j<Handover>(`/sites/${site}/handover`),
  original: (site: string) => j<string>(`/sites/${site}/config/original`),
  state: () => j<{ decisions: Decision[]; regressions: Regression[]; packages: Record<string, Pkg[]> }>('/state'),
  monitor: (variant: string) => j<MonitorRun>(`/monitor/${variant}`),
  lesson: (text: string, author: string, incident: string) => j<Regression>('/lessons', { site: 'h1', text, author, incident }),
  evaluation: () => j<Evaluation>('/evaluation'),
};

/** Probe once per page: live backend or the snapshot. */
export async function probe(): Promise<Status | null> {
  try { return await rf.status(); } catch { return null; }
}

/** Live only: make sure site h1 has an accepted package (the wrong-rack fix, decided by `author`). */
export async function ensurePackage(author: string): Promise<Pkg> {
  const st = await rf.state();
  const have = st.packages.h1 ?? [];
  if (have.length) return have[have.length - 1];
  const { flags } = await rf.flag('h1');
  const existing = st.decisions.find((d) => d.site === 'h1' && d.status === 'active');
  const d = existing ?? await rf.decide('h1', flags[0].zone, author);
  await rf.propose('h1');
  await rf.saveRegression('h1', d.id, author);
  return rf.accept('h1', author);
}
